import * as React from 'react'
import { ArrowDown } from 'lucide-react'
import { cn } from '@/lib/utils'

/*
 * MessageScroller — the scroll container for a conversation.
 *
 * It owns scroll behaviour only (never message rendering):
 *  - auto-follow: while the reader is within `threshold` px of the bottom, new
 *    messages and streamed growth of the last one keep the log pinned there.
 *    Growth is observed with a ResizeObserver on the content, not timers.
 *  - any upward scroll by the reader stops following (even inside `threshold`)
 *    and reveals the jump-to-latest button, which counts messages appended
 *    while the reader was away. Following resumes on reaching the bottom, or
 *    on a downward move back inside `threshold`.
 *  - `onReachTop` fires on scrolling into the top `threshold`, and also when
 *    the history doesn't overflow the viewport at all (no scroll can happen) —
 *    once per first message, so a page that loads nothing can't loop.
 *  - prepend preservation: when older history is inserted above the first
 *    message, scrollTop is shifted by the scrollHeight delta so the viewport
 *    stays on the same message. `overflow-anchor: none` turns off the browser's
 *    own scroll anchoring so the two never double-apply.
 *
 * Messages are found by their `data-message-id` attribute.
 */

export interface MessageScrollerScrollOptions {
  behavior?: ScrollBehavior
}

export interface MessageScrollerScrollToMessageOptions
  extends MessageScrollerScrollOptions {
  block?: 'start' | 'center' | 'end'
}

export interface MessageScrollerHandle {
  /** Scroll to the newest content and resume auto-follow. */
  scrollToBottom: (options?: MessageScrollerScrollOptions) => void
  /** Scroll a `[data-message-id]` element into view. Returns false when not found. */
  scrollToMessage: (id: string, options?: MessageScrollerScrollToMessageOptions) => boolean
  /** Whether the viewport is currently within `threshold` of the bottom. */
  isAtBottom: () => boolean
}

interface MessageScrollerContextValue {
  setViewport: (node: HTMLDivElement | null) => void
  setContent: (node: HTMLDivElement | null) => void
  handleScroll: () => void
  jumpToLatest: () => void
  focusViewport: () => void
  /** +1 when a consumer-placed jump button mounts, -1 when it unmounts. */
  registerJumpButton: (delta: number) => void
  atBottom: boolean
  unread: number
  streaming: boolean
}

const MessageScrollerContext = React.createContext<MessageScrollerContextValue | null>(null)

// True only around the root's own auto-placed jump button, so it doesn't
// count as a consumer-placed one.
const AutoJumpButtonContext = React.createContext(false)

function useMessageScrollerContext(part: string) {
  const ctx = React.useContext(MessageScrollerContext)
  if (!ctx) throw new Error(`<${part}> must be used within <MessageScroller>`)
  return ctx
}

function prefersReducedMotion() {
  return (
    typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}

function scrollViewport(viewport: HTMLElement, top: number, behavior: ScrollBehavior) {
  if (behavior === 'smooth' && !prefersReducedMotion() && typeof viewport.scrollTo === 'function') {
    viewport.scrollTo({ top, behavior: 'smooth' })
  } else {
    viewport.scrollTop = top
  }
}

function distanceFromBottom(el: HTMLElement) {
  return el.scrollHeight - el.scrollTop - el.clientHeight
}

function messageIds(content: HTMLElement) {
  return Array.from(content.querySelectorAll('[data-message-id]'), (node) =>
    node.getAttribute('data-message-id')
  )
}

export interface MessageScrollerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Marks the log `aria-busy` while a response is streaming. */
  streaming?: boolean
  /** Distance in px from the bottom (and top) that still counts as "at" it. */
  threshold?: number
  /** Called once each time the reader scrolls into the top `threshold` — load older history here. */
  onReachTop?: () => void
}

const MessageScroller = React.forwardRef<MessageScrollerHandle, MessageScrollerProps>(
  ({ className, children, streaming = false, threshold = 48, onReachTop, ...props }, ref) => {
    // Elements live in refs (they're mutated — scrollTop). `attached` bumps
    // only when a *new* element mounts, so the observer effect re-runs then —
    // and an unstable consumer ref (null → same node each render) can't loop.
    const viewportRef = React.useRef<HTMLDivElement | null>(null)
    const contentRef = React.useRef<HTMLDivElement | null>(null)
    const seenRef = React.useRef(new WeakSet<HTMLDivElement>())
    const [attached, setAttached] = React.useState(0)
    const attach = React.useCallback(
      (target: React.MutableRefObject<HTMLDivElement | null>, node: HTMLDivElement | null) => {
        target.current = node
        if (node && !seenRef.current.has(node)) {
          seenRef.current.add(node)
          setAttached((n) => n + 1)
        }
      },
      []
    )
    const setViewport = React.useCallback(
      (node: HTMLDivElement | null) => attach(viewportRef, node),
      [attach]
    )
    const setContent = React.useCallback(
      (node: HTMLDivElement | null) => attach(contentRef, node),
      [attach]
    )
    // `atBottom` mirrors "following": false is what shows the jump button.
    const [atBottom, setAtBottom] = React.useState(true)
    const [unread, setUnread] = React.useState(0)
    const [customJumpButtons, setCustomJumpButtons] = React.useState(0)

    const followingRef = React.useRef(true)
    // Last measured geometry + boundary ids. scrollHeight is only recorded by
    // `sync` (the ResizeObserver), never by the scroll handler, so a scroll
    // event landing between a prepend and its observation can't hide the delta.
    const snapshotRef = React.useRef({
      scrollTop: 0,
      scrollHeight: 0,
      firstId: null as string | null,
      lastId: null as string | null,
      nearTop: true,
      // First message id when onReachTop last fired for non-overflowing content.
      reachTopFiredFor: undefined as string | null | undefined,
    })
    const onReachTopRef = React.useRef(onReachTop)
    React.useEffect(() => {
      onReachTopRef.current = onReachTop
    }, [onReachTop])

    const sync = React.useCallback(() => {
      const viewport = viewportRef.current
      const content = contentRef.current
      if (!viewport || !content) return
      const snap = snapshotRef.current
      const ids = messageIds(content)
      const firstId = ids[0] ?? null
      const lastId = ids[ids.length - 1] ?? null

      // Messages appended after the previously-last one (for the unread badge).
      let appended = 0
      if (snap.lastId !== null && lastId !== snap.lastId) {
        const index = ids.lastIndexOf(snap.lastId)
        if (index !== -1) appended = ids.length - 1 - index
      }
      // History inserted above the previously-first message.
      const prepended =
        snap.firstId !== null && firstId !== snap.firstId && ids.includes(snap.firstId)

      if (followingRef.current) {
        viewport.scrollTop = viewport.scrollHeight
      } else if (prepended) {
        viewport.scrollTop = snap.scrollTop + (viewport.scrollHeight - snap.scrollHeight)
      }

      if (distanceFromBottom(viewport) <= 1) followingRef.current = true
      if (followingRef.current) setUnread(0)
      else if (appended > 0) setUnread((n) => n + appended)
      setAtBottom(followingRef.current)

      snap.scrollTop = viewport.scrollTop
      snap.scrollHeight = viewport.scrollHeight
      snap.firstId = firstId
      snap.lastId = lastId

      // Nothing to scroll means no top-zone transition will ever happen, so ask
      // for more history directly — again only once the first message changed.
      const fits = viewport.scrollHeight - viewport.clientHeight <= threshold
      if (fits && snap.reachTopFiredFor !== firstId) {
        snap.reachTopFiredFor = firstId
        onReachTopRef.current?.()
      }
    }, [threshold])

    React.useEffect(() => {
      const viewport = viewportRef.current
      const content = contentRef.current
      if (!viewport || !content) return
      sync()
      if (typeof ResizeObserver === 'undefined') return
      const observer = new ResizeObserver(() => sync())
      observer.observe(content)
      observer.observe(viewport)
      return () => observer.disconnect()
    }, [attached, sync])

    const handleScroll = React.useCallback(() => {
      const viewport = viewportRef.current
      if (!viewport) return
      const snap = snapshotRef.current
      const top = viewport.scrollTop
      const distance = distanceFromBottom(viewport)
      // Our own scrolls never read as upward: sync/prepend anchoring/
      // scrollToBottom only move down and record snap.scrollTop afterwards, and
      // a clamp from shrinking content lands exactly at the bottom.
      if (distance <= 1) followingRef.current = true
      else if (top < snap.scrollTop - 1) followingRef.current = false
      else if (distance <= threshold) followingRef.current = true
      if (followingRef.current) setUnread(0)
      setAtBottom(followingRef.current)
      snap.scrollTop = top

      const nearTop = top <= threshold
      if (nearTop && !snap.nearTop) onReachTopRef.current?.()
      snap.nearTop = nearTop
    }, [threshold])

    const scrollToBottom = React.useCallback(
      ({ behavior = 'smooth' }: MessageScrollerScrollOptions = {}) => {
        const viewport = viewportRef.current
        if (!viewport) return
        followingRef.current = true
        setUnread(0)
        setAtBottom(true)
        scrollViewport(viewport, viewport.scrollHeight, behavior)
        snapshotRef.current.scrollTop = viewport.scrollTop
      },
      []
    )

    const scrollToMessage = React.useCallback(
      (id: string, { behavior = 'smooth', block = 'start' }: MessageScrollerScrollToMessageOptions = {}) => {
        const viewport = viewportRef.current
        const content = contentRef.current
        if (!viewport || !content) return false
        const target = Array.from(content.querySelectorAll<HTMLElement>('[data-message-id]')).find(
          (node) => node.getAttribute('data-message-id') === id
        )
        if (!target) return false
        const rect = target.getBoundingClientRect()
        let top = rect.top - viewport.getBoundingClientRect().top + viewport.scrollTop
        if (block === 'center') top -= (viewport.clientHeight - rect.height) / 2
        if (block === 'end') top -= viewport.clientHeight - rect.height
        const maxTop = Math.max(0, viewport.scrollHeight - viewport.clientHeight)
        top = Math.min(maxTop, Math.max(0, top))
        followingRef.current = maxTop - top <= threshold
        setAtBottom(followingRef.current)
        scrollViewport(viewport, top, behavior)
        snapshotRef.current.scrollTop = viewport.scrollTop
        return true
      },
      [threshold]
    )

    React.useImperativeHandle(
      ref,
      () => ({
        scrollToBottom,
        scrollToMessage,
        isAtBottom: () =>
          viewportRef.current ? distanceFromBottom(viewportRef.current) <= threshold : true,
      }),
      [scrollToBottom, scrollToMessage, threshold]
    )

    const focusViewport = React.useCallback(
      () => viewportRef.current?.focus({ preventScroll: true }),
      []
    )
    // Stable, so a consumer jump button's register effect runs once per mount.
    const registerJumpButton = React.useCallback(
      (delta: number) => setCustomJumpButtons((n) => n + delta),
      []
    )

    const contextValue = React.useMemo<MessageScrollerContextValue>(
      () => ({
        setViewport,
        setContent,
        handleScroll,
        jumpToLatest: () => scrollToBottom({ behavior: 'smooth' }),
        focusViewport,
        registerJumpButton,
        atBottom,
        unread,
        streaming,
      }),
      [
        setViewport,
        setContent,
        handleScroll,
        scrollToBottom,
        focusViewport,
        registerJumpButton,
        atBottom,
        unread,
        streaming,
      ]
    )

    return (
      <MessageScrollerContext.Provider value={contextValue}>
        <div
          data-slot="message-scroller"
          data-at-bottom={atBottom}
          className={cn('relative flex min-h-0 flex-col', className)}
          {...props}
        >
          {children}
          {/* Auto-placed unless a consumer's jump button is mounted anywhere inside. */}
          {customJumpButtons === 0 && (
            <AutoJumpButtonContext.Provider value={true}>
              <MessageScrollerJumpButton />
            </AutoJumpButtonContext.Provider>
          )}
        </div>
      </MessageScrollerContext.Provider>
    )
  }
)
MessageScroller.displayName = 'MessageScroller'

const MessageScrollerContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, children, onScroll, ...props }, ref) => {
  const { setViewport, setContent, handleScroll, streaming } =
    useMessageScrollerContext('MessageScrollerContent')
  const viewportRef = React.useCallback(
    (node: HTMLDivElement | null) => {
      setViewport(node)
      if (typeof ref === 'function') ref(node)
      else if (ref) ref.current = node
    },
    [setViewport, ref]
  )

  return (
    <div
      ref={viewportRef}
      role="log"
      aria-live="polite"
      aria-label="Conversation"
      // A keyboard user must be able to focus the region to scroll it.
      tabIndex={0}
      data-slot="message-scroller-content"
      {...props}
      aria-busy={streaming || undefined}
      onScroll={(event) => {
        onScroll?.(event)
        handleScroll()
      }}
      className={cn(
        'bk-scroll-fade min-h-0 flex-1 overflow-y-auto overscroll-contain [overflow-anchor:none] focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-inset focus-visible:ring-ring',
        className
      )}
    >
      <div
        ref={setContent}
        data-slot="message-scroller-list"
        className="flex min-h-full flex-col justify-end gap-4 p-4"
      >
        {children}
      </div>
    </div>
  )
})
MessageScrollerContent.displayName = 'MessageScrollerContent'

const MessageScrollerJumpButton = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement>
>(({ className, children, onClick, ...props }, ref) => {
  const ctx = useMessageScrollerContext('MessageScrollerJumpButton')
  const isAuto = React.useContext(AutoJumpButtonContext)
  const { registerJumpButton } = ctx
  React.useEffect(() => {
    if (isAuto) return
    registerJumpButton(1)
    return () => registerJumpButton(-1)
  }, [isAuto, registerJumpButton])

  if (ctx.atBottom) return null
  const count = ctx.unread > 99 ? '99+' : String(ctx.unread)

  return (
    <button
      ref={ref}
      type="button"
      data-slot="message-scroller-jump-button"
      aria-label={
        ctx.unread > 0
          ? `Jump to latest message, ${ctx.unread} new`
          : 'Jump to latest message'
      }
      {...props}
      onClick={(event) => {
        onClick?.(event)
        if (event.defaultPrevented) return
        // The button unmounts once following resumes; hand keyboard focus to
        // the log instead of letting it fall to <body>.
        if (document.activeElement === event.currentTarget) ctx.focusViewport()
        ctx.jumpToLatest()
      }}
      className={cn(
        'absolute bottom-4 right-4 z-10 inline-flex h-11 w-11 items-center justify-center border-3 border-foreground bg-primary text-primary-foreground shadow-[4px_4px_0px_hsl(var(--shadow-color))] transition duration-200 animate-in fade-in-0 slide-in-from-bottom-2 hover:translate-x-[4px] hover:translate-y-[4px] hover:shadow-none focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring focus-visible:ring-offset-2',
        className
      )}
    >
      {children ?? <ArrowDown className="h-5 w-5" strokeWidth={3} aria-hidden="true" />}
      {ctx.unread > 0 && (
        <span
          aria-hidden="true"
          className="absolute -right-3 -top-3 flex h-6 min-w-6 items-center justify-center border-2 border-foreground bg-accent px-1 text-xs font-bold text-accent-foreground"
        >
          {count}
        </span>
      )}
    </button>
  )
})
MessageScrollerJumpButton.displayName = 'MessageScrollerJumpButton'

export { MessageScroller, MessageScrollerContent, MessageScrollerJumpButton }

import * as React from 'react'
import { cn } from '@/lib/utils'

/*
 * Message — one conversation row. Layout is a two-column grid (avatar | body);
 * the parts read `from` / `grouped` off the row's data attributes through
 * `group/message` variants, so they need no context and compose in any order.
 *
 *   user      → avatar on the right, body right-aligned
 *   assistant → avatar on the left, body left-aligned
 *   system    → centred, no avatar
 *
 * `grouped` marks a follow-up from the same author: the header is dropped and
 * the avatar keeps its column width but collapses, so bubbles stay aligned.
 */

export type MessageFrom = 'user' | 'assistant' | 'system'

// Body parts sit in the column opposite the avatar.
const bodyColumn =
  'group-data-[from=user]/message:col-start-1 group-data-[from=assistant]/message:col-start-2'

export interface MessageProps extends React.HTMLAttributes<HTMLDivElement> {
  from?: MessageFrom
  /** Consecutive message from the same author: hide header, collapse avatar. */
  grouped?: boolean
}

const Message = React.forwardRef<HTMLDivElement, MessageProps>(
  ({ className, from = 'assistant', grouped = false, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="message"
      data-from={from}
      data-grouped={grouped}
      className={cn(
        'group/message grid w-full gap-x-3 gap-y-1.5',
        from === 'user' && 'grid-cols-[minmax(0,1fr)_auto] justify-items-end',
        from === 'assistant' && 'grid-cols-[auto_minmax(0,1fr)] justify-items-start',
        from === 'system' && 'grid-cols-1 justify-items-center',
        grouped && '-mt-2',
        className
      )}
      {...props}
    />
  )
)
Message.displayName = 'Message'

const MessageAvatar = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="message-avatar"
      className={cn(
        'row-span-3 row-start-1 shrink-0 self-start',
        'group-data-[from=user]/message:col-start-2 group-data-[from=assistant]/message:col-start-1 group-data-[from=system]/message:hidden',
        // Grouped: keep the column width (bubbles stay aligned) but take no height.
        'group-data-[grouped=true]/message:invisible group-data-[grouped=true]/message:h-0 group-data-[grouped=true]/message:overflow-hidden',
        className
      )}
      {...props}
    />
  )
)
MessageAvatar.displayName = 'MessageAvatar'

export interface MessageHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Author name, rendered bold and uppercase. */
  name?: React.ReactNode
  /** Display timestamp, e.g. "10:42". */
  timestamp?: React.ReactNode
  /** Machine-readable value for the `<time>` element, e.g. an ISO string. */
  dateTime?: string
}

const MessageHeader = React.forwardRef<HTMLDivElement, MessageHeaderProps>(
  ({ className, name, timestamp, dateTime, children, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="message-header"
      className={cn(
        'flex items-baseline gap-2 text-xs',
        bodyColumn,
        'group-data-[from=user]/message:flex-row-reverse group-data-[grouped=true]/message:hidden',
        className
      )}
      {...props}
    >
      {name != null && <span className="font-bold uppercase tracking-wide">{name}</span>}
      {timestamp != null && (
        <time dateTime={dateTime} className="font-mono text-muted-foreground">
          {timestamp}
        </time>
      )}
      {children}
    </div>
  )
)
MessageHeader.displayName = 'MessageHeader'

const MessageContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="message-content"
      className={cn(
        'flex min-w-0 max-w-[min(85%,42rem)] flex-col items-start gap-2',
        bodyColumn,
        'group-data-[from=user]/message:items-end group-data-[from=system]/message:items-center',
        className
      )}
      {...props}
    />
  )
)
MessageContent.displayName = 'MessageContent'

const MessageFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="message-footer"
      className={cn(
        'flex items-center gap-1.5 pt-1 text-xs',
        bodyColumn,
        'group-data-[from=user]/message:flex-row-reverse',
        className
      )}
      {...props}
    />
  )
)
MessageFooter.displayName = 'MessageFooter'

export { Message, MessageAvatar, MessageHeader, MessageContent, MessageFooter }

import * as React from 'react'
import { cn } from '@/lib/utils'

/*
 * Bubble — the hard-edged message surface. No tail: the offset shadow does the
 * pointing, falling towards the author's side (right for assistant/start,
 * left for user/end). With `align="auto"` it reads the side from an enclosing
 * <Message> via `group/message`.
 */

export type BubbleVariant = 'default' | 'primary' | 'muted' | 'outline'
export type BubbleAlign = 'auto' | 'start' | 'end'

export interface BubbleReaction {
  emoji: string
  count: number
  /** Accessible name for the emoji, e.g. "thumbs up". Defaults to the emoji. */
  label?: string
  /** The current user reacted with this emoji. */
  active?: boolean
}

const variantClasses: Record<BubbleVariant, string> = {
  default: 'bg-card text-card-foreground',
  primary: 'bg-primary text-primary-foreground',
  muted: 'bg-muted text-foreground',
  outline: 'bg-transparent text-foreground',
}

const shadowStart = 'shadow-[4px_4px_0px_hsl(var(--shadow-color))]'
const shadowEnd = 'shadow-[-4px_4px_0px_hsl(var(--shadow-color))]'
const alignClasses: Record<BubbleAlign, string> = {
  start: shadowStart,
  end: shadowEnd,
  auto: `${shadowStart} group-data-[from=user]/message:shadow-[-4px_4px_0px_hsl(var(--shadow-color))]`,
}

export interface BubbleProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: BubbleVariant
  /** Which side the shadow falls towards. `auto` follows the enclosing Message. */
  align?: BubbleAlign
  /** Clamp the content to this many lines with a "Show more" toggle when it overflows. */
  collapsedLines?: number
  reactions?: BubbleReaction[]
  /** Makes reaction chips toggle buttons. */
  onReactionClick?: (reaction: BubbleReaction, index: number) => void
}

const Bubble = React.forwardRef<HTMLDivElement, BubbleProps>(
  (
    {
      className,
      variant = 'default',
      align = 'auto',
      collapsedLines,
      reactions,
      onReactionClick,
      children,
      ...props
    },
    ref
  ) => {
    const contentId = React.useId()
    const contentRef = React.useRef<HTMLDivElement>(null)
    const [expanded, setExpanded] = React.useState(false)
    const [overflowing, setOverflowing] = React.useState(false)
    const collapsible = collapsedLines != null && collapsedLines > 0
    const clamped = collapsible && !expanded

    // Only measurable while clamped; once expanded, the toggle must stay so
    // the reader can collapse again.
    React.useEffect(() => {
      const el = contentRef.current
      if (!el || !clamped) return
      const measure = () => setOverflowing(el.scrollHeight > el.clientHeight + 1)
      measure()
      if (typeof ResizeObserver === 'undefined') return
      const observer = new ResizeObserver(measure)
      observer.observe(el)
      return () => observer.disconnect()
    }, [clamped, collapsedLines, children])

    return (
      <div
        ref={ref}
        data-slot="bubble"
        data-variant={variant}
        className={cn(
          'w-fit max-w-full border-3 border-foreground px-4 py-3 text-sm leading-relaxed break-words',
          // Links and inline code inside message text.
          '[&_a]:font-bold [&_a]:underline [&_a]:decoration-2 [&_a]:underline-offset-2 [&_a:hover]:decoration-4',
          '[&_code]:border-2 [&_code]:border-current [&_code]:px-1 [&_code]:font-mono [&_code]:text-[0.9em]',
          variantClasses[variant],
          variant === 'outline' ? 'shadow-none' : alignClasses[align],
          className
        )}
        {...props}
      >
        <div
          ref={contentRef}
          id={contentId}
          data-slot="bubble-content"
          data-state={collapsible ? (expanded ? 'expanded' : 'collapsed') : undefined}
          className={cn('space-y-2', clamped && 'overflow-hidden')}
          style={
            clamped
              ? { display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: collapsedLines }
              : undefined
          }
        >
          {children}
        </div>

        {collapsible && (overflowing || expanded) && (
          <button
            type="button"
            aria-expanded={expanded}
            aria-controls={contentId}
            onClick={() => setExpanded((v) => !v)}
            className="mt-2 text-xs font-bold uppercase tracking-wide underline decoration-2 underline-offset-4 hover:decoration-4 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring"
          >
            {expanded ? 'Show less' : 'Show more'}
          </button>
        )}

        {reactions && reactions.length > 0 && (
          <ul aria-label="Reactions" className="mt-3 flex flex-wrap gap-1.5">
            {reactions.map((reaction, index) => {
              const chip = cn(
                'inline-flex items-center gap-1 border-2 border-foreground px-1.5 py-0.5 text-xs font-bold',
                reaction.active
                  ? 'bg-accent text-accent-foreground'
                  : 'bg-background text-foreground'
              )
              const label = `${reaction.label ?? reaction.emoji}: ${reaction.count}`
              return (
                <li key={`${reaction.emoji}-${index}`}>
                  {onReactionClick ? (
                    <button
                      type="button"
                      aria-pressed={!!reaction.active}
                      aria-label={label}
                      onClick={() => onReactionClick(reaction, index)}
                      className={cn(
                        chip,
                        'shadow-[2px_2px_0px_hsl(var(--shadow-color))] transition duration-200 hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-none focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring'
                      )}
                    >
                      <span aria-hidden="true">{reaction.emoji}</span>
                      <span aria-hidden="true">{reaction.count}</span>
                    </button>
                  ) : (
                    <span className={chip}>
                      <span aria-hidden="true">{reaction.emoji}</span>
                      <span aria-hidden="true">{reaction.count}</span>
                      <span className="sr-only">{label}</span>
                    </span>
                  )}
                </li>
              )
            })}
          </ul>
        )}
      </div>
    )
  }
)
Bubble.displayName = 'Bubble'

export { Bubble }

import * as React from 'react'
import { Download, File, FileAudio, FileCode, FileText, FileVideo, Image, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Progress } from '@/components/ui/progress'

/*
 * Attachment — a file or image card inside a message.
 *
 * When the card opens something (`href` or `onOpen`) it uses the
 * stretched-link pattern: the file name is the one real link/button and its
 * ::after covers the card, while the action buttons sit above it (z-10) as
 * siblings — never nested inside another interactive element.
 */

export type AttachmentState = 'uploading' | 'done' | 'error'

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 Bytes'
  const k = 1024
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(k)), sizes.length - 1)
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
}

function getFileIcon(mimeType = '') {
  if (mimeType.startsWith('image/')) return Image
  if (mimeType.startsWith('video/')) return FileVideo
  if (mimeType.startsWith('audio/')) return FileAudio
  if (mimeType.includes('pdf') || mimeType.includes('document')) return FileText
  if (mimeType.includes('code') || mimeType.includes('javascript') || mimeType.includes('json'))
    return FileCode
  return File
}

export interface AttachmentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** File name — also the accessible name of the open link and actions. */
  name: string
  /** Size in bytes. */
  size?: number
  /** MIME type, picks the file icon. */
  type?: string
  /** Image preview URL. When set, the card renders as an image card. */
  src?: string
  /** Alt text for the preview. The file name is shown beside it, so it defaults to "". */
  alt?: string
  /** Preview aspect ratio (width / height). */
  aspectRatio?: number
  /** Makes the whole card a link. */
  href?: string
  /** Makes the whole card a button (ignored when `href` is set). */
  onOpen?: () => void
  state?: AttachmentState
  /** Upload progress 0–100. Omit while uploading for an indeterminate bar. */
  progress?: number
  /** Error message for `state="error"`. */
  error?: string
  onDownload?: () => void
  onRemove?: () => void
}

const actionClass =
  'relative z-10 flex h-8 w-8 shrink-0 items-center justify-center border-2 border-foreground bg-background text-foreground transition duration-200 hover:-translate-x-0.5 hover:-translate-y-0.5 hover:shadow-[2px_2px_0px_hsl(var(--shadow-color))] focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring'

const Attachment = React.forwardRef<HTMLDivElement, AttachmentProps>(
  (
    {
      className,
      name,
      size,
      type,
      src,
      alt = '',
      aspectRatio = 4 / 3,
      href,
      onOpen,
      state = 'done',
      progress,
      error,
      onDownload,
      onRemove,
      children,
      ...props
    },
    ref
  ) => {
    const uploading = state === 'uploading'
    const failed = state === 'error'
    // An in-flight upload has nothing to open yet.
    const opens = !uploading && (href != null || onOpen != null)
    const isImage = src != null

    const stretched =
      'after:absolute after:inset-0 after:content-[""] focus-visible:outline-none focus-visible:after:ring-3 focus-visible:after:ring-ring focus-visible:after:ring-offset-2'
    const nameClass = 'block truncate text-sm font-bold'
    const title = opens ? (
      href != null ? (
        <a href={href} className={cn(nameClass, stretched, 'hover:underline')}>
          {name}
        </a>
      ) : (
        <button
          type="button"
          onClick={onOpen}
          className={cn(nameClass, stretched, 'max-w-full text-left hover:underline')}
        >
          {name}
        </button>
      )
    ) : (
      <span className={nameClass}>{name}</span>
    )

    let meta: React.ReactNode = size != null ? formatBytes(size) : null
    if (uploading) meta = progress != null ? `Uploading · ${Math.round(progress)}%` : 'Uploading…'
    if (failed) meta = error ?? 'Upload failed'

    return (
      <div
        ref={ref}
        data-slot="attachment"
        data-state={state}
        className={cn(
          'relative flex w-72 max-w-full flex-col border-3 border-foreground bg-card text-card-foreground shadow-[4px_4px_0px_hsl(var(--shadow-color))] transition duration-200',
          opens && 'hover:translate-x-[4px] hover:translate-y-[4px] hover:shadow-none',
          failed && 'border-destructive shadow-[4px_4px_0px_hsl(var(--destructive))]',
          className
        )}
        {...props}
      >
        {isImage && (
          <div className="overflow-hidden border-b-3 border-inherit" style={{ aspectRatio }}>
            <img
              src={src}
              alt={alt}
              className={cn('h-full w-full object-cover', uploading && 'opacity-60')}
            />
          </div>
        )}

        <div className="flex items-center gap-3 p-3">
          {!isImage && (
            <div className="flex h-10 w-10 shrink-0 items-center justify-center border-3 border-foreground bg-muted">
              {/* A lookup of module-level icons, not a component created during render. */}
              {React.createElement(getFileIcon(type), { className: 'h-5 w-5', 'aria-hidden': true })}
            </div>
          )}
          <div className="min-w-0 flex-1">
            {title}
            {meta != null && (
              <p
                className={cn(
                  'text-xs font-bold uppercase tracking-wide',
                  failed ? 'text-destructive' : 'text-muted-foreground'
                )}
              >
                {meta}
              </p>
            )}
          </div>
          {(onDownload || onRemove || children) && (
            <div className="relative z-10 flex shrink-0 items-center gap-1.5">
              {children}
              {onDownload && !uploading && !failed && (
                <button
                  type="button"
                  aria-label={`Download ${name}`}
                  onClick={onDownload}
                  className={cn(actionClass, 'hover:bg-primary hover:text-primary-foreground')}
                >
                  <Download className="h-4 w-4" strokeWidth={2.5} aria-hidden="true" />
                </button>
              )}
              {onRemove && (
                <button
                  type="button"
                  aria-label={uploading ? `Cancel upload of ${name}` : `Remove ${name}`}
                  onClick={onRemove}
                  className={cn(actionClass, 'hover:bg-destructive hover:text-destructive-foreground')}
                >
                  <X className="h-4 w-4" strokeWidth={2.5} aria-hidden="true" />
                </button>
              )}
            </div>
          )}
        </div>

        {uploading && (
          <div className="px-3 pb-3">
            <Progress
              value={progress}
              variant={progress == null ? 'marquee' : 'smooth'}
              aria-label={`Uploading ${name}`}
              className="h-3 border-2 shadow-none"
            />
          </div>
        )}
      </div>
    )
  }
)
Attachment.displayName = 'Attachment'

export { Attachment }

import * as React from 'react'
import { cn } from '@/lib/utils'

/*
 * Marker — inline status rows inside the conversation log:
 *   note      — a system note ("ADA JOINED THE CHAT")
 *   separator — a labeled rule ("TODAY")
 *   status    — live activity ("SEARCHING THE WEB…"); `active` adds the
 *               `.bk-shimmer` text effect while the work is in flight.
 *
 * No live-region role of its own: inside MessageScroller the surrounding
 * role="log" already announces it, and a nested live region double-announces.
 */

export type MarkerVariant = 'note' | 'separator' | 'status'

export interface MarkerProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: MarkerVariant
  /** Streaming / tool activity in progress — shimmers the label. */
  active?: boolean
  icon?: React.ReactNode
}

const Marker = React.forwardRef<HTMLDivElement, MarkerProps>(
  ({ className, variant = 'note', active = false, icon, children, ...props }, ref) => {
    const label = (
      <span data-slot="marker-label" className={cn(active && 'bk-shimmer')}>
        {children}
      </span>
    )
    const iconNode = icon != null && (
      <span aria-hidden="true" className="flex shrink-0 items-center [&_svg]:h-4 [&_svg]:w-4">
        {icon}
      </span>
    )

    return (
      <div
        ref={ref}
        data-slot="marker"
        data-variant={variant}
        data-active={active}
        className={cn(
          'flex w-full items-center text-xs font-bold uppercase tracking-widest',
          variant === 'note' && 'justify-center',
          variant === 'separator' && 'gap-3',
          variant === 'status' && 'gap-2',
          className
        )}
        {...props}
      >
        {variant === 'separator' ? (
          <>
            <span aria-hidden="true" className="h-[3px] flex-1 bg-foreground" />
            <span className="inline-flex items-center gap-2 border-3 border-foreground bg-background px-2 py-0.5 shadow-[2px_2px_0px_hsl(var(--shadow-color))]">
              {iconNode}
              {label}
            </span>
            <span aria-hidden="true" className="h-[3px] flex-1 bg-foreground" />
          </>
        ) : variant === 'status' ? (
          <>
            {iconNode && (
              <span
                className={cn(
                  'flex h-7 w-7 shrink-0 items-center justify-center border-2 border-foreground',
                  active ? 'bg-accent text-accent-foreground' : 'bg-background'
                )}
              >
                {iconNode}
              </span>
            )}
            {label}
          </>
        ) : (
          <span className="inline-flex items-center gap-2 border-2 border-dashed border-foreground bg-muted px-3 py-1 text-foreground">
            {iconNode}
            {label}
          </span>
        )}
      </div>
    )
  }
)
Marker.displayName = 'Marker'

export { Marker }
